<?php
ob_start();
require_once '../config.php';
require_once '../includes/gemini.php';

if(!isset($_SESSION['user_id'])||($_SESSION['role']??'')!=='admin'){
    if(isset($_GET['ck_upload'])&&$_GET['ck_upload']=='1'){header('Content-Type: application/json; charset=utf-8');http_response_code(403);echo json_encode(['uploaded'=>0,'error'=>['message'=>'Phiên quản trị không hợp lệ']],JSON_UNESCAPED_UNICODE);exit;}
    header('Location: ../dang-nhap');exit;
}

if(isset($_GET['ck_upload'])&&$_GET['ck_upload']=='1'){
    header('Content-Type: application/json; charset=utf-8');
    $upload_dir='../uploads/';
    if(!is_dir($upload_dir))mkdir($upload_dir,0777,true);
    if(isset($_FILES['upload'])){
        $fileName=save_uploaded_media($_FILES['upload'],$upload_dir,'news');
        if($fileName){echo json_encode(['uploaded'=>1,'fileName'=>$fileName,'url'=>media_url($fileName,$base_url)],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}else{echo json_encode(['uploaded'=>0,'error'=>['message'=>'Định dạng ảnh không được hỗ trợ hoặc lỗi tải lên']],JSON_UNESCAPED_UNICODE);}
    }else{echo json_encode(['uploaded'=>0,'error'=>['message'=>'Lỗi file ảnh']],JSON_UNESCAPED_UNICODE);} 
    exit;
}

include 'header.php';
$upload_dir='../uploads/';if(!is_dir($upload_dir))mkdir($upload_dir,0777,true);
$msg_type='';$msg_text='';if(isset($_SESSION['msg'])){$msg_type=$_SESSION['msg']['type'];$msg_text=$_SESSION['msg']['text'];unset($_SESSION['msg']);}

if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['action'])){
    csrf_guard();
    $action=$_POST['action'];
    if($action==='add'||$action==='edit'){
        $title=trim((string)($_POST['title']??''));$content=(string)($_POST['content']??'');$id=(int)($_POST['id']??0);$oldThumbnail=(string)($_POST['old_thumbnail']??'');$thumbnail=$oldThumbnail;$thumbnailUrl=trim((string)($_POST['thumbnail_url']??''));
        if($thumbnailUrl!==''){
            if(!valid_remote_media_url($thumbnailUrl)){$_SESSION['msg']=['type'=>'error','text'=>'Link ảnh bìa không hợp lệ. Hãy dùng URL bắt đầu bằng http:// hoặc https://'];header('Location: news.php');exit;}
            $thumbnail=$thumbnailUrl;
        }
        $uploadedThumbnail=save_uploaded_media($_FILES['thumbnail']??null,$upload_dir,'news');
        if($uploadedThumbnail===false){$_SESSION['msg']=['type'=>'error','text'=>'Ảnh bìa tải lên không hợp lệ. Chỉ hỗ trợ JPG, JPEG, PNG, GIF, WEBP hoặc AVIF.'];header('Location: news.php');exit;}
        if($uploadedThumbnail!==null)$thumbnail=$uploadedThumbnail;
        if($action==='add'){$stmt=$conn->prepare('INSERT INTO news (title,thumbnail,content) VALUES (?,?,?)');$stmt->bind_param('sss',$title,$thumbnail,$content);}else{$stmt=$conn->prepare('UPDATE news SET title=?,thumbnail=?,content=? WHERE id=?');$stmt->bind_param('sssi',$title,$thumbnail,$content,$id);} 
        $ok=$stmt->execute();$stmt->close();if($ok&&$action==='edit'&&$thumbnail!==$oldThumbnail)delete_local_media($oldThumbnail,$upload_dir);$_SESSION['msg']=['type'=>$ok?'success':'error','text'=>$ok?($action==='add'?'Thêm tin tức thành công!':'Cập nhật tin tức thành công!'):'Có lỗi xảy ra!'];header('Location: news.php');exit;
    }
    if($action==='delete'){
        $id=(int)($_POST['id']??0);$stmt=$conn->prepare('SELECT thumbnail FROM news WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();$row=$stmt->get_result()->fetch_assoc();$stmt->close();$stmt=$conn->prepare('DELETE FROM news WHERE id=?');$stmt->bind_param('i',$id);$ok=$stmt->execute();$stmt->close();if($ok&&$row)delete_local_media($row['thumbnail']??'',$upload_dir);$_SESSION['msg']=['type'=>$ok?'success':'error','text'=>$ok?'Đã xóa bài viết!':'Có lỗi xảy ra!'];header('Location: news.php');exit;
    }
}

$search=trim((string)($_GET['search']??''));$page=max(1,(int)($_GET['page']??1));$limit=6;$where='WHERE 1=1';if($search!=='')$where.=" AND title LIKE '%".$conn->real_escape_string($search)."%'";$total=(int)$conn->query("SELECT COUNT(*) c FROM news $where")->fetch_assoc()['c'];$pages=max(1,(int)ceil($total/$limit));$page=min($page,$pages);$offset=($page-1)*$limit;$result=$conn->query("SELECT * FROM news $where ORDER BY id DESC LIMIT $limit OFFSET $offset");$writerModel=gemini_get_setting($conn,'gemini_writer_model','gemini-3.5-flash');$modelOptions=gemini_model_options();$writerName=$modelOptions[$writerModel]??$writerModel;
?>
<style>
